SPECIES=$(printf '%s\n' "${!P[@]}" | sort)
i=0
for sp in $SPECIES; do
  base=$((11000 + 10*i)); i=$((i+1))
  for j in 0 1 2; do
    seed=$((base + j))
    f="$OUT/${sp}_baby_s${seed}.png"
    [ -f "$f" ] && { echo "skip $f"; continue; }
    PORTRAIT_SIZE=1024 ./tools/portrait -s "$seed" -o "$f" "${P[$sp]}, $STYLE" || echo "FAILED $sp $seed"
  done
done
echo DONE
